pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, bytes memory data, uint256 value, uint256 seed) public {
        // Ensure msg.sender != Owner (to avoid Command being called by Owner and transferring everything)
        vm.assume(adr != address(0) && adr != address(c.Owner()) && data.length <= 256);
        value = bound(value, 0, 100 ether);

        // Fund the contract with some ether
        uint256 initialBalance = bound(seed, 0, 100 ether);
        vm.deal(address(c), initialBalance);

        // Record the Owner's balance before the Command call
        address owner = c.Owner();
        uint256 ownerPreBalance = owner.balance;

        // Call Command as non-Owner (should revert)
        vm.prank(adr);
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSelector(c.Command.selector, adr, data));

        // The rule: if Command reverts, the Owner's balance should not decrease
        uint256 ownerPostBalance = owner.balance;
        assertTrue(success == false || ownerPostBalance >= ownerPreBalance);
    }
}

