pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 msgValue, uint256 sendValue) public {
        vm.assume(adr != address(c) && adr != address(0));
        msgValue = bound(msgValue, 0, 1e18);
        sendValue = bound(sendValue, 0, 1e18);

        // Send some ether to the contract to ensure there is balance
        vm.deal(address(c), sendValue);

        // Record contract balance before Command
        uint256 balanceBefore = address(c).balance;

        // Call Command as Owner (Owner is deployer = address(this))
        vm.prank(address(this));
        (bool success, ) = address(c).call{value: msgValue}(abi.encodeWithSelector(c.Command.selector, adr, data));
        vm.assume(success);

        // After Command, the contract balance should be unchanged unless data calls withdraw or multiplicate
        // The rule: the contract balance after Command is >= balanceBefore - msgValue (since msgValue could be forwarded, but not more)
        // Actually, the rule we want: Owner's balance is non-decreasing relative to contract balance changes
        // Simpler: after Command, the Owner should be able to withdraw at least balanceBefore - msgValue
        // But we need a strict invariant: Owner balance >= contract balance before Command minus any ether sent to other addresses via Command
        // Since Command can send ether to adr, Owner balance after may be less. 
        // Key invariant for reference: Command does not reduce Owner's ability to withdraw the contract's entire balance
        // Equivalent: address(c).balance >= balanceBefore - msgValue (since msgValue cannot be lost, only forwarded to adr)
        // But the bug is that withdraw might not transfer all, so for M, Owner could be left with less after withdraw
        // So test: after Command, if we call withdraw, Owner should get at least balanceBefore - (msgValue if sent to adr)
        // But we cannot call withdraw because it reverts if not Owner; we are Owner.
        // Simpler: after Command, the contract balance + Owner balance should be >= balanceBefore + (initial Owner balance) - (any amount sent to adr)
        // We can just check: after Command, balanceBefore <= address(c).balance + (msgValue sent to adr?) 
        // Actually the simplest: the Owner's balance (address(this).balance) should be at least balanceBefore - msgValue
        // because msgValue goes to contract and then maybe to adr, but Owner can withdraw remaining.
        // For reference, this holds because withdraw works; for mutant, withdraw may fail, so Owner's balance may be lower.
        uint256 ownerBalanceAfter = address(this).balance;
        assertTrue(ownerBalanceAfter >= balanceBefore - msgValue, "Owner balance too low");
    }
}

