    C c;
    CalldataRecorder recorder;
    function setUp() public {
        c = new C();
        recorder = new CalldataRecorder();
    }
    function testFuzz_property(address caller, bytes memory data, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(data.length > 0);
        vm.assume(amount > 0 && amount <= 1 ether);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.Command(address(recorder), data);
        assertTrue(keccak256(recorder.lastCalldata()) == keccak256(data));
    }
}

