pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 commandValue, address adrMulti) public {
        // Bound commandValue to avoid overflow in reference
        commandValue = bound(commandValue, 0, address(c).balance);
        // Ensure the caller is Owner (initially test contract)
        vm.assume(adrMulti != address(0));

        // Send some initial balance to contract
        vm.deal(address(c), 1 ether);

        // Record balance before Command
        uint256 balanceBeforeCommand = address(c).balance;

        // Call Command with some value
        c.Command{value: commandValue}(adr, data);

        // Check that multiplicate with msg.value = balance (no-op should not transfer balance away)
        uint256 balanceBeforeMulti = address(c).balance;
        uint256 msgVal = balanceBeforeMulti;

        // Call multiplicate with msg.value = contract balance
        (bool success, ) = address(c).call{value: msgVal}(abi.encodeWithSelector(c.multiplicate.selector, adrMulti));

        // The rule: after Command, calling multiplicate with msg.value = balance should not decrease contract balance below balanceBeforeCommand
        assertTrue(address(c).balance >= balanceBeforeCommand);
    }
}

