pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, bytes memory data, uint256 balanceSeed) public {
        // Ensure contract has some balance
        vm.deal(address(c), balanceSeed);

        // Make a call to Command with value 0 (doesn't change balance but uses the function)
        c.Command(adr, data);

        uint256 balBefore = address(c).balance;
        uint256 msgVal = balBefore; // msg.value equals contract balance

        // Get the address of the contract to record recipient balance before
        address recipient = adr;
        uint256 recvBefore = recipient.balance;

        // Call multiplicate with msg.value = contract balance
        (bool ok, ) = address(c).call{value: msgVal}(abi.encodeWithSignature("multiplicate(address)", adr));

        uint256 balAfter = address(c).balance;
        uint256 recvAfter = recipient.balance;

        // Rule: The call should succeed (no revert) and the contract balance should be 0 after
        // But in the buggy version, success leads to a transfer that drains more than allowed or does something else
        // Actually the difference: In reference, the if-condition msg.value >= address(this).balance is true
        // and it transfers address(this).balance + msg.value = 2*balance, which would cause revert due to insufficient balance after transfer
        // So in reference, the call reverts. In buggy, it transfers just msg.value (balance) and succeeds.
        // We assert that the call should revert.
        assertTrue(!ok, "multiplicate should fail when msg.value equals contract balance");
    }
}

