pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 commandValue) public {
        // Ensure the contract has some initial balance
        vm.deal(address(c), 1 ether);

        // Make the contract callable by the test contract
        vm.deal(address(this), commandValue);

        // Record balance before Command
        uint256 balanceBeforeCommand = address(c).balance;

        // Call Command
        (bool success, ) = address(c).call{value: commandValue}(abi.encodeWithSignature("Command(address,bytes)", adr, data));

        // If Command reverted, skip this test case
        if (!success) return;

        // Record balance after Command
        uint256 balanceAfterCommand = address(c).balance;

        // Now call multiplicate with msg.value = 0
        uint256 balanceBeforeMultiplicate = address(c).balance;
        (bool multiSuccess, ) = address(c).call{value: 0}(abi.encodeWithSignature("multiplicate(address)", adr));
        uint256 balanceAfterMultiplicate = address(c).balance;

        // The general rule: when multiplicate is called with msg.value = 0,
        // the contract's balance should not change (since msg.value < balance always)
        assertTrue(multiSuccess == false || balanceAfterMultiplicate == balanceBeforeMultiplicate);
    }
}
